<?php
namespace Agah\Erp\Modules\Payroll;
use Agah\Erp\Core\{Access,Audit,Business,Ctx,Db,Jalali,Money,Request,Sequence,ValidationException,ConflictException,NotFoundException};
use Agah\Erp\Modules\Accounting\{FiscalService,VoucherService};
if(!defined('ABSPATH'))exit;
final class PayrollService {
    public static function period($key){$key=Money::normDigits($key);if(!preg_match('/^(1[3-6][0-9]{2})-(0[1-9]|1[0-2])$/D',$key,$m))throw new ValidationException(['period_key'=>'ماه به شکل 1405-07 وارد شود.']);$days=Jalali::monthLength((int)$m[1],(int)$m[2]);return [$key,Jalali::parse($m[1].'/'.$m[2].'/01'),Jalali::parse($m[1].'/'.$m[2].'/'.$days),$days];}
    public static function employee($cid,$id,array $in){return Access::write($cid,$id?'payroll.edit':'payroll.create',function()use($cid,$id,$in){$old=$id?Business::row('employees',$cid,$id):null;$name=Request::clean($in['name']??'',190);$code=Request::clean($in['code']??'',30);if(mb_strlen($name)<2||!preg_match('/^[A-Za-z0-9_-]{1,30}$/D',$code))throw new ValidationException(['name'=>'نام و کد معتبر لازم است.']);if(Db::val('SELECT id FROM '.Db::t('employees').' WHERE company_id=%d AND code=%s AND id<>%d',$cid,$code,$id))throw new ValidationException(['code'=>'کد تکراری است.']);
        $detail=$old?(int)$old['detail_id']:Db::insert('details',['company_id'=>$cid,'code'=>'EMP'.Sequence::next($cid,'employee',0),'name'=>$name,'kind'=>'other','ref_type'=>'employee','created_at'=>gmdate('Y-m-d H:i:s')]);$data=['name'=>$name,'code'=>$code,'detail_id'=>$detail,'is_active'=>empty($in['is_active'])?0:1];$id=Business::save('employees',$cid,$id,$data);Db::update('details',['name'=>$name],['company_id'=>$cid,'id'=>$detail]);Audit::log('payroll.employee','employee',$id,$old,$data,$cid);return $id;});}
    const CONTRACT_TYPES=['full'=>'تمام‌وقت','part'=>'پاره‌وقت','hourly'=>'ساعتی','project'=>'پروژه‌ای'];
    /** مبالغ و نوع قرارداد؛ ساعتی/پروژه‌ای حقوق پایهٔ ماهانه ندارند و نرخ خودشان را لازم دارند. */
    private static function contractTerms(array $in){
        $type=$in['contract_type']??'full';if(!isset(self::CONTRACT_TYPES[$type]))throw new ValidationException(['contract_type'=>'نوع قرارداد معتبر نیست.']);
        $daily=in_array($type,['full','part'],true);
        $t=['contract_type'=>$type,'base_salary'=>Business::amount($in['base_salary']??($daily?null:0),$daily),'benefits'=>Business::amount($in['benefits']??null),'hourly_rate'=>Business::amount($in['hourly_rate']??0,$type==='hourly'),'project_amount'=>Business::amount($in['project_amount']??0,$type==='project'),'weekly_minutes'=>$type==='part'?PayrollMath::integer($in['weekly_minutes']??null,60,3600):0];
        foreach(['benefits_insurance_exempt','benefits_tax_exempt','overtime_base_extra'] as $k){$t[$k]=Business::amount($in[$k]??0);if($t[$k]>$t['benefits'])throw new ValidationException([$k=>'جزء مزایا از کل بیشتر است.']);}
        $items=[];foreach((array)($in['items']??[]) as $code=>$amount){$code=strtoupper((string)$code);if(!preg_match('/^[A-Z0-9_]{1,30}$/D',$code)||!PayItemService::exists($code))throw new ValidationException(['items'=>'قلم حقوق «'.$code.'» تعریف نشده است.']);$items[$code]=Business::amount($amount);}
        ksort($items);$t['items_json']=$items?wp_json_encode($items):null;return $t;
    }
    public static function contract($cid,$id,array $in){return Access::write($cid,'payroll.edit',function()use($cid,$id,$in){
        $old=$id?Business::row('contracts',$cid,$id):null;$used=$id?Db::rows('SELECT period_key FROM '.Db::t('payslips').' WHERE company_id=%d AND contract_id=%d',$cid,$id):[];
        $eid=Business::id($in['employee_id']??0);Business::row('employees',$cid,$eid);$start=Business::date($in['start_date']??'');$end=Business::date($in['end_date']??'');$terms=self::contractTerms($in);
        if($used||($id&&Db::val('SELECT id FROM '.Db::t('payroll_run_lines').' WHERE company_id=%d AND contract_id=%d LIMIT 1',$cid,$id))){
            if((int)$old['employee_id']!==$eid||$old['start_date']!==$start)throw new ConflictException('مبلغ، شروع یا کارمند قرارداد استفاده‌شده تغییر نمی‌کند.');
            foreach($terms as $k=>$v)if((string)($old[$k]??'')!==(string)($v??''))throw new ConflictException('مبلغ و اجزای قرارداد استفاده‌شده تغییر نمی‌کند؛ از «نسخهٔ تازهٔ قرارداد» استفاده کنید.');
            foreach($used as $slip){[,,$issuedEnd]=self::period($slip['period_key']);if($end<min($old['end_date'],$issuedEnd))throw new ConflictException('پایان قرارداد نباید دوره محاسبه‌شده را کوتاه کند.');}
        }
        if($end<$start)throw new ValidationException(['end_date'=>'بازه قرارداد معتبر نیست.']);
        if(Db::val('SELECT id FROM '.Db::t('contracts').' WHERE company_id=%d AND employee_id=%d AND id<>%d AND start_date<=%s AND end_date>=%s',$cid,$eid,$id,$end,$start))throw new ConflictException('قراردادهای یک کارمند هم‌پوشانی دارند.');
        $data=$terms+['employee_id'=>$eid,'start_date'=>$start,'end_date'=>$end];$id=Business::save('contracts',$cid,$id,$data);Audit::log('payroll.contract','contract',$id,$old,$data,$cid);return $id;});}
    /**
     * نسخهٔ تازهٔ قرارداد از تاریخ معین: نسخهٔ قبلی تا روز پیش از آن کوتاه و نسخهٔ تازه با همان کارمند و پایان ساخته می‌شود.
     * دوره‌ای که فیش یا لیست حقوق دارد کوتاه نمی‌شود؛ پس محاسبهٔ گذشته بازنویسی نمی‌شود.
     */
    public static function amendContract($cid,$id,$from,array $in){return Access::write($cid,'payroll.edit',function()use($cid,$id,$from,$in){
        $old=Business::row('contracts',$cid,$id,true);$from=Business::date($from);if($from<=$old['start_date']||$from>$old['end_date'])throw new ValidationException(['from'=>'تاریخ نسخهٔ تازه باید داخل بازهٔ قرارداد و پس از شروع آن باشد.']);
        $cut=Jalali::addDays($from,-1);
        foreach(Db::col('SELECT period_key FROM '.Db::t('payslips')." WHERE company_id=%d AND contract_id=%d AND status='issued'",$cid,$id) as $key){[,,$pend]=self::period($key);if($pend>$cut)throw new ConflictException('برای ماه '.$key.' با این قرارداد فیش صادر شده است؛ نسخهٔ تازه از پس از آن ماه شروع شود.');}
        if(Db::val('SELECT l.id FROM '.Db::t('payroll_run_lines').' l JOIN '.Db::t('payroll_runs')." r ON r.company_id=l.company_id AND r.id=l.run_id WHERE l.company_id=%d AND l.contract_id=%d AND r.status IN ('final','paid') LIMIT 1",$cid,$id))foreach(Db::col('SELECT DISTINCT r.period_key FROM '.Db::t('payroll_run_lines').' l JOIN '.Db::t('payroll_runs')." r ON r.company_id=l.company_id AND r.id=l.run_id WHERE l.company_id=%d AND l.contract_id=%d AND r.status IN ('final','paid')",$cid,$id) as $key){[,,$pend]=self::period($key);if($pend>$cut)throw new ConflictException('لیست حقوق ماه '.$key.' با این قرارداد قطعی شده است.');}
        $base=array_intersect_key($old,array_flip(['contract_type','base_salary','benefits','benefits_insurance_exempt','benefits_tax_exempt','overtime_base_extra','hourly_rate','project_amount','weekly_minutes']));$base['items']=json_decode((string)$old['items_json'],true)?:[];
        foreach($base as $k=>$v)if(!array_key_exists($k,$in))$in[$k]=is_numeric($v)&&$k!=='contract_type'?(int)$v:$v;
        $terms=self::contractTerms($in);
        Db::update('contracts',['end_date'=>$cut,'updated_at'=>gmdate('Y-m-d H:i:s')],['company_id'=>$cid,'id'=>$id]);
        $new=Business::save('contracts',$cid,0,$terms+['employee_id'=>(int)$old['employee_id'],'start_date'=>$from,'end_date'=>$old['end_date'],'version'=>(int)$old['version']+1,'parent_id'=>(int)$old['id']]);
        Audit::log('payroll.contract.version','contract',$new,['contract'=>(int)$id,'end_date'=>$old['end_date']],['from'=>$from,'terms'=>$terms],$cid);return $new;});}
    private static function year($cid,$start,$end){$fy=FiscalService::assertOpen($cid,$end);if($start<$fy['start_date'])throw new ValidationException(['period_key'=>'ماه باید داخل یک سال مالی باشد.']);FiscalService::assertOpen($cid,$start);return (int)$fy['id'];}
    public static function attendance($cid,array $in){return Access::write($cid,'payroll.edit',function()use($cid,$in){[$key,$start,$end,$days]=self::period($in['period_key']??'');$fy=self::year($cid,$start,$end);$eid=Business::id($in['employee_id']??0);Business::row('employees',$cid,$eid);if(Db::val('SELECT id FROM '.Db::t('payslips')." WHERE company_id=%d AND employee_id=%d AND period_key=%s AND status='issued'",$cid,$eid,$key))throw new ConflictException('کارکرد فیش صادرشده تغییر نمی‌کند.');if(Db::val('SELECT l.id FROM '.Db::t('payroll_run_lines').' l JOIN '.Db::t('payroll_runs')." r ON r.company_id=l.company_id AND r.id=l.run_id WHERE l.company_id=%d AND l.employee_id=%d AND r.period_key=%s AND r.status IN ('sent','adjusting','final','paid') LIMIT 1",$cid,$eid,$key))throw new ConflictException('کارکرد ماهی که لیست حقوقش قفل یا قطعی شده تغییر نمی‌کند.');
            $data=['employee_id'=>$eid,'fiscal_year_id'=>$fy,'period_key'=>$key];foreach(['work_days','leave_days'] as $k)$data[$k]=PayrollMath::integer($in[$k]??null,0,$days);foreach(['mission_days','absence_days'] as $k)$data[$k]=PayrollMath::integer($in[$k]??0,0,$days);if($data['work_days']+$data['leave_days']+$data['mission_days']+$data['absence_days']>$days)throw new ValidationException(['attendance'=>'جمع کارکرد، مرخصی، مأموریت و غیبت بیش از روزهای ماه است.']);$data['work_minutes']=PayrollMath::integer($in['work_minutes']??0,0,44640);$data['project_permille']=PayrollMath::integer($in['project_permille']??0,0,1000);$data['overtime_minutes']=PayrollMath::integer($in['overtime_minutes']??null,0,20000);foreach(['extra_benefits','deductions','extra_insurance_exempt','extra_tax_exempt'] as $k)$data[$k]=Business::amount($in[$k]??0);foreach(['extra_insurance_exempt','extra_tax_exempt'] as $k)if($data[$k]>$data['extra_benefits'])throw new ValidationException([$k=>'جزء معاف بیش از مزایا است.']);$old=Db::row('SELECT * FROM '.Db::t('attendance').' WHERE company_id=%d AND employee_id=%d AND period_key=%s',$cid,$eid,$key);$id=Business::save('attendance',$cid,(int)($old['id']??0),$data);Audit::log('payroll.attendance','attendance',$id,$old,$data,$cid);return $id;});}
    private static function account($cid,$id,array $classes,$detail=false){$a=Business::row('accounts',$cid,$id);if(!$a['is_active']||(int)$a['level']!==3||!in_array($a['stmt_class'],$classes,true)||($detail?($a['detail_rule']==='none'||$a['detail_kind']!==''):$a['detail_rule']==='required'))throw new ValidationException(['accounts'=>'حساب معین فعال با طبقه و تفصیلی سازگار انتخاب کنید.']);return (int)$a['id'];}
    public static function params($cid,$year,array $p){return Access::write($cid,'payroll.edit',function()use($cid,$year,$p){$fy=Business::row('fiscal_years',$cid,$year);if($fy['status']!=='open')throw new ConflictException('سال مالی بسته است.');$p['formula']='ir_daily_v1';$p['insurance_tax_numerator']=$p['insurance_tax_numerator']??1;$p['insurance_tax_denominator']=$p['insurance_tax_denominator']??1;$p=PayrollMath::params($p);$p['expense_account_id']=self::account($cid,Business::id($p['expense_account_id']??0),['opex']);$p['salary_account_id']=self::account($cid,Business::id($p['salary_account_id']??0),['liability_current'],true);foreach(['insurance_account_id','tax_account_id','deduction_account_id'] as $k)$p[$k]=self::account($cid,Business::id($p[$k]??0),['liability_current']);$old=Db::row('SELECT * FROM '.Db::t('payroll_params').' WHERE company_id=%d AND fiscal_year_id=%d',$cid,$year);$id=Business::save('payroll_params',$cid,(int)($old['id']??0),['fiscal_year_id'=>$year,'params_json'=>wp_json_encode($p)]);Audit::log('payroll.params','payroll_params',$id,$old,['fiscal_year_id'=>$year,'params'=>$p],$cid);return $id;});}
    public static function issue($cid,$employee,$period,$date){return Access::write($cid,'payroll.approve',function()use($cid,$employee,$period,$date){[$key,$start,$end,$days]=self::period($period);$fy=self::year($cid,$start,$end);$date=Business::date($date);$postfy=FiscalService::assertOpen($cid,$date);if($date<$end||(int)$postfy['id']!==$fy)throw new ValidationException(['date'=>'تاریخ سند پس از پایان ماه و در همان سال مالی باشد.']);$e=Business::row('employees',$cid,$employee);if(!$e['is_active'])throw new ConflictException('کارمند غیرفعال است.');if(Db::val('SELECT id FROM '.Db::t('payslips')." WHERE company_id=%d AND employee_id=%d AND period_key=%s AND status='issued'",$cid,$employee,$key))throw new ConflictException('حقوق این ماه قبلاً صادر شده است.');$contracts=Db::rows('SELECT * FROM '.Db::t('contracts').' WHERE company_id=%d AND employee_id=%d AND start_date<=%s AND end_date>=%s',$cid,$employee,$end,$start);if(count($contracts)>1)throw new ConflictException('دو قرارداد در یک ماه وجود دارد؛ این نسخه محاسبه چندقراردادی یک ماه را نمی‌پذیرد.');$c=$contracts[0]??null;$a=Db::row('SELECT * FROM '.Db::t('attendance').' WHERE company_id=%d AND employee_id=%d AND period_key=%s',$cid,$employee,$key);$p=Db::val('SELECT params_json FROM '.Db::t('payroll_params').' WHERE company_id=%d AND fiscal_year_id=%d',$cid,$fy);if(!$c||!$a||!$p)throw new ValidationException(['payroll'=>'قرارداد، کارکرد و پارامتر سال لازم است.']);$eligible=Jalali::diffDays(max($start,$c['start_date']),min($end,$c['end_date']))+1;if((int)$a['work_days']+(int)$a['leave_days']>$eligible)throw new ValidationException(['attendance'=>'روزهای حقوق‌پذیر بیش از پوشش قرارداد در این ماه است.']);$p=json_decode($p,true);if(($p['formula']??'')!=='ir_daily_v1')throw new ValidationException(['params'=>'پارامترهای قدیمی حقوق را برای سال انتخاب‌شده بازبینی و دوباره ذخیره کنید.']);
        self::account($cid,$p['expense_account_id'],['opex']);self::account($cid,$p['salary_account_id'],['liability_current'],true);foreach(['insurance_account_id','tax_account_id','deduction_account_id'] as $k)self::account($cid,$p[$k],['liability_current']);$ci=$c;foreach(['base_salary','benefits','benefits_insurance_exempt','benefits_tax_exempt','overtime_base_extra'] as $k)$ci[$k]=(int)($ci[$k]??0);$ai=$a;foreach(['work_days','leave_days','overtime_minutes','extra_benefits','deductions','extra_insurance_exempt','extra_tax_exempt'] as $k)$ai[$k]=(int)($ai[$k]??0);$calc=PayrollMath::calculate($ci,$ai,$p,$days);
        $data=array_intersect_key($calc,array_flip(['gross','insurance_employee','insurance_employer','tax','deductions','net']));$snap=['company'=>array_intersect_key(Ctx::company(),array_flip(['name','legal_name','economic_code'])),'employee'=>$e,'contract'=>$c,'attendance'=>$a,'params'=>$p,'calculation'=>$calc,'eligible_days'=>$eligible];$id=Business::save('payslips',$cid,0,$data+['employee_id'=>$employee,'contract_id'=>$c['id'],'attendance_id'=>$a['id'],'fiscal_year_id'=>$fy,'period_key'=>$key,'number'=>Sequence::next($cid,'payroll',$fy),'doc_date'=>$date,'snapshot'=>wp_json_encode($snap)]);
        foreach($calc as $kind=>$amount)Business::save('payslip_items',$cid,0,['payslip_id'=>$id,'kind'=>$kind,'amount'=>$amount]);$lines=[['account_id'=>$p['expense_account_id'],'debit'=>Money::add($calc['gross'],$calc['insurance_employer'])]];
        foreach([['salary_account_id',$calc['net'],(int)$e['detail_id']],['insurance_account_id',Money::add($calc['insurance_employee'],$calc['insurance_employer']),0],['tax_account_id',$calc['tax'],0],['deduction_account_id',$calc['deductions'],0]] as [$k,$amount,$did])if($amount)$lines[]=['account_id'=>$p[$k],'detail_id'=>$did,'credit'=>$amount];$vid=VoucherService::postSystem(['voucher_date'=>$date,'description'=>'حقوق '.$e['name'].' '.$key,'source_type'=>'payroll','source_id'=>$id],$lines);Db::update('payslips',['voucher_id'=>$vid],['company_id'=>$cid,'id'=>$id]);Audit::log('payroll.issue','payslip',$id,null,['net'=>$calc['net'],'voucher_id'=>$vid],$cid);return $id;
    });}
    public static function voidDocument($cid,$id,$reason){return Access::write($cid,'payroll.delete',function()use($cid,$id,$reason){$r=Business::row('payslips',$cid,$id,true);if($r['status']!=='issued')throw new ConflictException('فیش صادرشده لازم است.');if(!empty($r['run_id']))throw new ConflictException('فیش لیست حقوق فقط با «برگشت» همان لیست باطل می‌شود.');VoucherService::voidSystem((int)$r['voucher_id'],Business::reason($reason));Db::update('payslips',['status'=>'void','active_slot'=>null],['company_id'=>$cid,'id'=>$id]);Audit::log('payroll.void','payslip',$id,['status'=>'issued'],['reason'=>$reason],$cid);});}
    public static function get($cid,$id){Access::need($cid,'payroll.view');$r=Business::row('payslips',$cid,$id);$r['items']=Db::rows('SELECT kind,amount FROM '.Db::t('payslip_items').' WHERE company_id=%d AND payslip_id=%d',$cid,$id);return $r;}
    public static function report($cid,$year,$page=1){Access::need($cid,'payroll.view');$year=Business::id($year);$page=max(1,(int)$page);$where='company_id=%d'.($year?' AND fiscal_year_id=%d':'');$args=$year?[$cid,$year]:[$cid];$n=(int)Db::val('SELECT COUNT(*) FROM '.Db::t('payslips').' WHERE '.$where,...$args);$s=Db::row('SELECT COALESCE(SUM(gross),0) gross,COALESCE(SUM(net),0) net,COALESCE(SUM(tax),0) tax,COALESCE(SUM(insurance_employee+insurance_employer),0) insurance FROM '.Db::t('payslips')." WHERE $where AND status='issued'",...$args);return ['rows'=>Db::rows('SELECT id,number,employee_id,period_key,doc_date,status,gross,net,tax,insurance_employee,insurance_employer FROM '.Db::t('payslips').' WHERE '.$where.' ORDER BY id DESC LIMIT 50 OFFSET %d',...array_merge($args,[($page-1)*50])),'totals'=>$s,'pages'=>(int)ceil($n/50),'page'=>$page,'count'=>$n];}
}
